package com.kafka.backend.naverarchive;

import static org.assertj.core.api.Assertions.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;

@EnabledIfEnvironmentVariable(named="ARCHIVE_TEST_DB",matches="jdbc:postgresql://127\\.0\\.0\\.1:55457/postgres")
class NaverRssPostgresTest {
 static final UUID A=UUID.fromString("a1230000-0000-4000-8000-000000000001"),B=UUID.fromString("a1230000-0000-4000-8000-000000000002");
 ThreadLocal<UUID> user=ThreadLocal.withInitial(()->A);JdbcTemplate db;ArchiveService s;String schema;NaverRssSyncService rss;MutableClock clock=new MutableClock();AtomicInteger calls=new AtomicInteger();NaverRssFeed.Feed feed;NaverRssFeed.Failure failure;
 static class MutableClock extends Clock {Instant value=Instant.parse("2026-11-21T00:00:00Z");public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return value;}void advance(){value=value.plusSeconds(600);}}
 @BeforeEach void setup()throws Exception{schema="rss_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(System.getenv("ARCHIVE_TEST_DB"),"archive_test","");db=new JdbcTemplate(source);db.execute("create schema "+schema);source.setUrl(System.getenv("ARCHIVE_TEST_DB")+"?currentSchema="+schema+",public");for(String file:List.of("V116__naver_owner_archive.sql","V121__naver_native_upload_parts.sql","V123__naver_rss_discovery.sql"))db.execute(Files.readString(Path.of("src/main/resources/db/migration/"+file)));s=new ArchiveService(db,user::get,new DataSourceTransactionManager(source));feed=make(entry("1","recent",clock.instant(),"short..."));rss=new NaverRssSyncService(s,()->{calls.incrementAndGet();if(failure!=null)throw failure;return feed;},true,clock);}
 @AfterEach void cleanup(){user.remove();db.execute("drop schema "+schema+" cascade");}
 NaverRssFeed.Entry entry(String id,String title,Instant date,String excerpt){return new NaverRssFeed.Entry(id,title,"synthetic",date,"https://blog.naver.com/yozo990/"+id,excerpt,ArchiveContent.hash(id+title+date+excerpt),true,0);}
 NaverRssFeed.Feed make(NaverRssFeed.Entry... items){var dates=Arrays.stream(items).map(NaverRssFeed.Entry::published).filter(Objects::nonNull).sorted().toList();return new NaverRssFeed.Feed(List.of(items),0,ArchiveContent.hash(Arrays.toString(items)),dates.isEmpty()?null:dates.getFirst(),dates.isEmpty()?null:dates.getLast());}
 Map<String,Object> run(){return rss.runNow(Map.of("requestId",UUID.randomUUID().toString()));}
 Map<String,Object> post(String title,String external,String body){var b=new LinkedHashMap<String,Object>();b.put("requestId",UUID.randomUUID().toString());b.put("title",title);b.put("bodyText",body);b.put("externalPostId",external);b.put("sourceHtml","<p>synthetic original</p>");b.put("originalPublishedAt","2026-11-17T01:41:00Z");return s.create(b,"WEB");}
 String state(String id){return db.queryForObject("select state from naver_archive_rss_items where owner_id=? and external_post_id=?",String.class,user.get(),id);}
 @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> page){return (List<Map<String,Object>>)page.get("items");}
 String snapshot(String table){return db.queryForObject("select md5(coalesce(string_agg(j,'' order by j),'')) from (select row_to_json(t)::text j from "+table+" t) q",String.class);}
 @Test void threeRunsReorderAndSourceEditsNeverChange351Archives(){var saved=post("existing","2","SYNTHETIC verbatim\r\n\r\n  한글\n");UUID id=ArchiveService.uuid(saved.get("id"));s.progress(id,Map.of("read",true,"position",0.4));for(int i=1;i<=350;i++)post("SYNTHETIC legacy "+i,null,"SYNTHETIC body "+i);var before=Map.of("posts",snapshot("naver_archive_posts"),"revisions",snapshot("naver_archive_revisions"),"progress",snapshot("naver_archive_read_progress"),"assets",snapshot("naver_archive_assets"));feed=make(entry("1","new",clock.instant(),"new..."),entry("2","existing",clock.instant(),"old..."));var request=Map.<String,Object>of("requestId",UUID.randomUUID().toString());var first=rss.runNow(request);assertThat(first.get("inserted")).isEqualTo(0);assertThat(first.get("discovered")).isEqualTo(1);assertThat(rss.runNow(request)).containsEntry("id",first.get("id"));assertThat(calls.get()).isEqualTo(1);clock.advance();feed=make(feed.items().getLast(),feed.items().getFirst());assertThat(run().get("unchanged")).isEqualTo(2);clock.advance();feed=make(entry("2","changed",clock.instant(),"edited..."),feed.items().getLast());assertThat(run().get("queueUpdated")).isEqualTo(1);assertThat(state("2")).isEqualTo("SOURCE_EDIT_REVIEW");assertThat(db.queryForObject("select count(*) from naver_archive_posts",Long.class)).isEqualTo(351);for(var e:before.entrySet())assertThat(snapshot("naver_archive_"+e.getKey().replace("progress","read_progress"))).isEqualTo(e.getValue());assertThat(db.queryForObject("select count(*) from naver_archive_rss_items",Integer.class)).isEqualTo(2);assertThat(s.get(id).get("bodyText")).isEqualTo("SYNTHETIC verbatim\r\n\r\n  한글\n");}
 @Test void oldFirstBaselineIsNotHistoricalImportAndUnknownDateIsPending(){feed=make(entry("1","old",clock.instant().minusSeconds(20*86400),"old..."),entry("2","undated",null,"missing..."));run();assertThat(state("1")).isEqualTo("BASELINE_ONLY");assertThat(state("2")).isEqualTo("PARTIAL_NEEDS_SOURCE");clock.advance();run();assertThat(state("1")).isEqualTo("BASELINE_ONLY");assertThat(rss.status().get("backlog")).isEqualTo(1L);assertThat(s.list(Map.of()).get("total")).isEqualTo(0L);}
 @Test void legacyPrefixIsReviewOnlyAndExplicitLinkPreservesContentAndProgress(){String prefix="SYNTHETIC 한글 원문 ".repeat(10);var saved=post("legacy",null,prefix+" full ending");UUID id=ArchiveService.uuid(saved.get("id"));s.progress(id,Map.of("read",true,"position",0.7));feed=make(entry("1","not a title match",clock.instant(),prefix+"..."));run();assertThat(state("1")).isEqualTo("POSSIBLE_DUPLICATE_REVIEW");assertThat(rows(rss.items(Map.of())).getFirst().get("duplicateCandidates")).asList().hasSize(1);var request=Map.<String,Object>of("postId",id.toString(),"requestId",UUID.randomUUID().toString(),"expectedVersion",1);var linked=rss.link("1",request);assertThat(rss.link("1",request).get("auditReceipt")).isEqualTo(linked.get("auditReceipt").toString());var actual=s.get(id);for(String field:List.of("bodyText","sourceHtml","safeHtml","sourceSha256","originalPublishedAt","assets"))assertThat(actual.get(field)).isEqualTo(saved.get(field));assertThat(actual.get("read")).isEqualTo(true);assertThat(actual.get("position")).isEqualTo(0.7);assertThat(actual.get("externalPostId")).isEqualTo("1");assertThat(actual.get("originalUrl")).isEqualTo("https://blog.naver.com/yozo990/1");assertThat(state("1")).isEqualTo("EXISTING_ARCHIVE");clock.advance();feed=make(entry("1","source edited",clock.instant(),"new excerpt..."));run();assertThat(state("1")).isEqualTo("SOURCE_EDIT_REVIEW");rss.link("1",request);assertThat(state("1")).isEqualTo("SOURCE_EDIT_REVIEW");assertThat(s.get(id).get("version")).isEqualTo(2L);}
 @Test void titleAloneNeverMatchesAndOtherOwnerCannotReadOrLink(){var saved=post("same",null,"unrelated full body");feed=make(entry("1","same",clock.instant(),"short..."));run();assertThat(state("1")).isEqualTo("PARTIAL_NEEDS_SOURCE");user.set(B);assertThat(rows(rss.items(Map.of()))).isEmpty();assertThatThrownBy(()->rss.link("1",Map.of("postId",saved.get("id"),"requestId",UUID.randomUUID().toString(),"expectedVersion",1))).isInstanceOf(ArchiveException.class);run();assertThatThrownBy(()->rss.link("1",Map.of("postId",saved.get("id"),"requestId",UUID.randomUUID().toString(),"expectedVersion",1))).isInstanceOf(ArchiveException.class);user.set(A);assertThat(s.get(ArchiveService.uuid(saved.get("id"))).get("version")).isEqualTo(1L);}
 @Test void rateLimitAndCircuitBreakerSurviveRetriesAndConfigUsesCas(){rss.configure(Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",0,"enabled",true));assertThat(rss.enabledOwners()).containsExactly(A);failure=new NaverRssFeed.Failure("RATE_LIMITED",false,clock.instant().plusSeconds(7200));assertThat(run().get("state")).isEqualTo("RETRYABLE_ERROR");clock.advance();assertThat(run().get("state")).isEqualTo("RETRY_LATER");assertThat(calls.get()).isEqualTo(1);clock.value=clock.value.plusSeconds(7200);failure=new NaverRssFeed.Failure("POLICY_BLOCKED",true,null);assertThat(run().get("state")).isEqualTo("POLICY_BLOCKED");assertThat(rss.status()).containsEntry("enabled",false).containsEntry("policyBlocked",true).containsEntry("version",2L);assertThat(run().get("state")).isEqualTo("POLICY_BLOCKED");assertThat(calls.get()).isEqualTo(2);assertThatThrownBy(()->rss.configure(Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",1,"enabled",true))).isInstanceOf(ArchiveException.class);assertThatThrownBy(()->rss.configure(Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",2,"enabled",true))).isInstanceOf(ArchiveException.class);}
 @Test void manualMinimumIntervalAndScheduledBucketAreIdempotent(){rss.configure(Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",0,"enabled",true));rss.scheduled();rss.scheduled();assertThat(calls.get()).isEqualTo(1);assertThat(run().get("state")).isEqualTo("MINIMUM_INTERVAL");clock.advance();rss.scheduled();assertThat(calls.get()).isEqualTo(2);assertThat(db.queryForObject("select count(*) from naver_archive_rss_runs where trigger_kind='SCHEDULED'",Integer.class)).isEqualTo(2);}
 @Test void concurrentFetchesAcrossOwnersUseSourceAdvisoryLock()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var slow=new NaverRssSyncService(s,()->{entered.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new RuntimeException();}catch(InterruptedException e){throw new RuntimeException(e);}return feed;},true,clock);try(var pool=Executors.newSingleThreadExecutor()){var first=pool.submit(()->slow.run(A,UUID.randomUUID(),"MANUAL"));assertThat(entered.await(5,TimeUnit.SECONDS)).isTrue();try{assertThat(rss.run(B,UUID.randomUUID(),"MANUAL").get("state")).isEqualTo("SKIPPED_OVERLAP");assertThatThrownBy(()->rss.configure(Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",1,"enabled",true))).isInstanceOf(ArchiveException.class);}finally{release.countDown();}assertThat(first.get(10,TimeUnit.SECONDS).get("state")).isEqualTo("SUCCESS_RSS_ONLY");}}
 @Test void sourceChangesRequireAcknowledgementAndHashCas(){var saved=post("existing","1","complete body");run();clock.advance();feed=make(entry("1","edited",clock.instant(),"changed..."));run();assertThat(state("1")).isEqualTo("SOURCE_EDIT_REVIEW");assertThatThrownBy(()->rss.acknowledge("1",Map.of("requestId",UUID.randomUUID().toString(),"sourceSha256","wrong"))).isInstanceOf(ArchiveException.class);rss.acknowledge("1",Map.of("requestId",UUID.randomUUID().toString(),"sourceSha256",feed.items().getFirst().hash()));assertThat(state("1")).isEqualTo("EXISTING_ARCHIVE");clock.advance();run();assertThat(state("1")).isEqualTo("EXISTING_ARCHIVE");assertThat(s.get(ArchiveService.uuid(saved.get("id"))).get("version")).isEqualTo(1L);}
 @Test void pendingPaginationRetainsAllIdsAndMissingFeedDoesNotDelete(){feed=make(entry("1","one",null,"one..."),entry("2","two",null,"two..."),entry("3","three",null,"three..."));run();Set<Object> ids=new HashSet<>();String cursor=null;do{var q=new HashMap<>(Map.of("limit","1"));if(cursor!=null)q.put("cursor",cursor);var page=rss.items(q);assertThat(ids.add(rows(page).getFirst().get("externalPostId"))).isTrue();cursor=(String)page.get("nextCursor");}while(cursor!=null);assertThat(ids).containsExactlyInAnyOrder("1","2","3");clock.advance();feed=make(entry("3","three",null,"three..."));run();assertThat(rss.status().get("backlog")).isEqualTo(3L);assertThatThrownBy(()->rss.items(Map.of("cursor","!"))).isInstanceOf(ArchiveException.class);assertThatThrownBy(()->rss.items(Map.of("limit","51"))).isInstanceOf(ArchiveException.class);}
 @Test void globalOffAndDisabledOwnerNeverScheduleFetch(){var off=new NaverRssSyncService(s,()->{throw new AssertionError("no network");},false,clock);assertThat(off.runNow(Map.of("requestId",UUID.randomUUID().toString())).get("state")).isEqualTo("DISABLED");assertThat(off.enabledOwners()).isEmpty();assertThatThrownBy(()->off.configure(Map.of("requestId",UUID.randomUUID().toString(),"expectedVersion",0,"enabled",true))).isInstanceOf(ArchiveException.class);rss.scheduled();assertThat(calls.get()).isZero();}
}
